class Solution {
    public void moveZeroes(int[] nums) {
        int n = nums.length;
        int[] tmp = new int[n];
        int m = 0;
        for (int x : nums) if (x != 0) tmp[m++] = x;
        for (int i = 0; i < m; i++) nums[i] = tmp[i];
        for (int i = m; i < n; i++) nums[i] = 0;
    }
}

