class Solution {
    public void moveZeroes(int[] nums) {
        int lastNonZero = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] != 0) {
                int tmp = nums[lastNonZero];
                nums[lastNonZero] = nums[i];
                nums[i] = tmp;
                lastNonZero++;
            }
        }
    }
}
